42	/**
43	 * Client-side protected route guard. Second line of defense — the Next.js
44	 * proxy (proxy.ts) is the primary gate and redirects before this runs.
45	 * Used inside protected route group layouts for UX (avoids flash during
46	 * initial client-side auth hydration).
47	 */
48	export const ProtectedRoute = ({ children }: { children: React.ReactNode }) => {
49	  const { user, loading } = useAuth();
50	  const router = useRouter();
51	
52	  useEffect(() => {
53	    if (!loading && !user) router.replace("/auth");
54	  }, [loading, user, router]);
55	
56	  if (loading || !user) return <AuthLoader />;
57	  return <>{children}</>;
58	};
59	
60	export const AdminRoute = ({ children }: { children: React.ReactNode }) => {
61	  const { user, loading, isAdmin } = useAuth();
62	  const router = useRouter();
63	
64	  useEffect(() => {
65	    if (loading) return;
66	    if (!user) router.replace("/auth");
67	    else if (!isAdmin) router.replace("/");
68	  }, [loading, user, isAdmin, router]);
69	
70	  if (loading || !user || !isAdmin) return <AuthLoader />;
71	  return <>{children}</>;
72	};
